#!/usr/bin/env python3
"""Read-only current Alice 17879 death/respawn/BDS offset snapshot. No game commands."""
import json,os,shlex,subprocess,sys
from pathlib import Path
REMOTE="\nimport json,os,subprocess,time,math\nfrom pathlib import Path\nroot=Path.home()/'.alice-bedrock-control'\nout={'state':'unverified','connected':False,'coreState':None,'followIntent':False,'health':None,'food':None,\n 'deathCountSinceTracking':None,'deathRecoveryPhase':None,'respawnCyclesThisSession':None,\n 'clientToBdsDistance':None,'clientToBdsDx':None,'clientToBdsDy':None,'clientToBdsDz':None,\n 'clientToLoginDistance':None,'loginToBdsDistance':None,'bdsSamples':None,\n 'bdsAgeSeconds':None,'samplePairAgeSeconds':None,'bdsPairTravel':None,\n 'navigationEvidenceEligibleNow':False,'witnessStatus':None,'outboundMovingQueued':None}\ntry:\n p=subprocess.run(['/usr/bin/python3',str(Path.home()/'minecraft-ai/scripts/alice-mint.py'),'status'],\n  capture_output=True,text=True,timeout=12)\n if p.returncode or len(p.stdout)>20000:raise ValueError('operator_status')\n op=json.loads(p.stdout)\n if op.get('statusSource')!='current_process' or op.get('processAlive') is not True:raise ValueError('not_current')\n f=root/'status.json';st=f.lstat()\n if not f.is_file() or f.is_symlink() or st.st_uid!=os.getuid() or st.st_mode&0o077 or st.st_size>8192:raise ValueError('status_identity')\n d=json.loads(f.read_text(encoding='utf-8'))\n if d.get('producerPid')!=op.get('pid') or d.get('world')!='Bedrock level' or d.get('serverPort')!=17879:raise ValueError('wrong_world')\n out['state']='observed'\n out['connected']=d.get('connected') is True and d.get('sessionEstablished') is True\n out['coreState']=d.get('state') if d.get('state') in ('FOLLOW','SURVIVE','COMBAT','GUARD','IDLE','RECOVER') else 'other'\n out['followIntent']=d.get('followTarget')=='MolarParsley191'\n for k in ('health','food'):\n  v=d.get(k)\n  if type(v) in (float,int) and 0<=v<=20:out[k]=v\n n=(d.get('life') or {}).get('deathsSinceTracking')\n if type(n) is int and 0<=n<=1000000:out['deathCountSinceTracking']=n\n death=d.get('deathRecovery') or {}\n out['deathRecoveryPhase']=death.get('phase') if death.get('phase') in ('idle','respawn_verified','respawn_stalled','health_restored_awaiting_spawn','waiting_for_server_respawn','server_ready_seen','respawn_ready_retried_waiting_for_server','server_ready_to_spawn','spawn_without_positive_health','transport_closed_during_respawn') else 'other'\n n=death.get('cycles')\n if type(n) is int and 0<=n<=100000:out['respawnCyclesThisSession']=n\n m=d.get('movementEvidence') or {}\n n=m.get('independentSamples')\n if type(n) is int and 0<=n<10000000:out['bdsSamples']=n\n now=int(time.time()*1000)\n a,b=m.get('independentAt'),m.get('independentPreviousAt')\n if type(a) is int and a<=now and a>0:out['bdsAgeSeconds']=round((now-a)/1000,2)\n if type(b) is int and b<=now and b>0:out['samplePairAgeSeconds']=round((now-b)/1000,2)\n out['witnessStatus']=m.get('witnessStatus') if m.get('witnessStatus') in ('accepted','stale_or_invalid_witness','duplicate_or_rejected','unavailable','not_configured') else 'other'\n n=m.get('independentPairTravelBlocks')\n if type(n) in (float,int) and 0<=n<32:out['bdsPairTravel']=round(n,2)\n def point(x):\n  return isinstance(x,dict) and all(type(x.get(c)) in (int,float) and math.isfinite(x[c]) for c in ('x','y','z'))\n def delta(a,b):\n  return math.dist([a[k] for k in ('x','y','z')],[b[k] for k in ('x','y','z')])\n loc=d.get('position');bds=m.get('independentLatestFeet');login=m.get('loginFeet')\n if point(loc) and point(bds):\n  out['clientToBdsDistance']=round(delta(loc,bds),3)\n  for coord,key in [('x','clientToBdsDx'),('y','clientToBdsDy'),('z','clientToBdsDz')]:out[key]=round(loc[coord]-bds[coord],3)\n if point(loc) and point(login):out['clientToLoginDistance']=round(delta(loc,login),3)\n if point(login) and point(bds):out['loginToBdsDistance']=round(delta(login,bds),3)\n out['navigationEvidenceEligibleNow']=out['connected'] and out['bdsSamples'] is not None and out['bdsSamples']>=2 and out['samplePairAgeSeconds'] is not None and out['samplePairAgeSeconds']<=4 and out['clientToBdsDistance'] is not None and out['clientToBdsDistance']<=.75\n audit=root/'outbound-input-audit.json'\n if audit.is_file() and not audit.is_symlink() and audit.stat().st_uid==os.getuid() and audit.stat().st_mode&0o077==0 and audit.stat().st_size<8192:\n  raw=json.loads(audit.read_text());q=raw.get('movingQueued')\n  if type(q) is int and 0<=q<100000000:out['outboundMovingQueued']=q\nexcept (OSError,ValueError,KeyError,TypeError,subprocess.SubprocessError):pass\nprint(json.dumps(out,separators=(',',':')))\n"
def run(directory):
 out=Path(directory)
 if out.is_symlink() or not out.is_dir():raise ValueError('unsafe_output')
 record=None
 try:
  p=subprocess.run(['/usr/bin/ssh','-T','-o','BatchMode=yes','-o','ConnectTimeout=8','-o','StrictHostKeyChecking=yes','tedz@192.168.0.104','/usr/bin/python3 -c '+shlex.quote(REMOTE)],capture_output=True,text=True,timeout=50)
  if p.returncode==0 and len(p.stdout)<3000:record=json.loads(p.stdout)
 except (OSError,ValueError,subprocess.SubprocessError):pass
 result={'audit':'ALICE_FOLLOW_DEATH_POSITION_READONLY','schemaVersion':1,'readOnly':True,'bdsQueriesSent':0,'clientRestarted':False,'worldTouched':False,'observation':record}
 fd=os.open(out/'follow_death_position.json',os.O_WRONLY|os.O_EXCL|os.O_CREAT|getattr(os,'O_NOFOLLOW',0),0o600)
 with os.fdopen(fd,'w') as f:json.dump(result,f,separators=(',',':'));f.write('\n')
 print(json.dumps({'state':record.get('state') if isinstance(record,dict) else 'unavailable'}))
def selftest():
 assert 'deathsSinceTracking' in REMOTE and 'independentLatestFeet' in REMOTE
 assert 'navigationEvidenceEligibleNow' in REMOTE and 'serverPort' in REMOTE
 print('ALICE_FOLLOW_DEATH_POSITION_CONTRACT_PASS')
if __name__=='__main__':
 if sys.argv[1:]==['--self-test']:selftest()
 elif len(sys.argv)==3 and sys.argv[1]=='--read':run(sys.argv[2])
 else:raise SystemExit('usage: --self-test | --read OUTPUT_DIR')
